-- Sources behind the taper, race-week and race-day rules (verified via Crossref/PubMed, Oct 2026).
-- No peer-reviewed HYROX taper study exists yet: rules are extrapolated from endurance, strength and nutrition research.
insert into public.knowledge_sources (title, category, author, source_url, summary, takeaways) values
 ('Bosquet et al. (2007): effects of tapering on performance – meta-analysis', 'taper', 'Med Sci Sports Exerc 39(8):1358–1365',
  'https://doi.org/10.1249/mss.0b013e31806010e0',
  '27 studies. Best: a 2-week taper (ES 0.59), volume −41–60 % (ES 0.72), intensity kept (ES 0.33) and frequency kept (ES 0.35).',
  array['Taper = last 2 weeks: ~65 % then ~40 % of normal volume','Keep the short, sharp efforts','Keep the number of sessions (≥ 80 %)']),
 ('Mujika & Padilla (2003): scientific bases for precompetition tapering', 'taper', 'Med Sci Sports Exerc 35(7):1182–1187',
  'https://doi.org/10.1249/01.MSS.0000074448.73931.11',
  'Keep intensity, cut volume 60–90 %, cut frequency no more than ~20 %; progressive non-linear tapers beat step tapers; typical gain ~3 % (0.5–6 %).',
  array['Progressive taper: volume drops further in race week','Frequency cut ≤ 20 % → short easy runs instead of extra rest days']),
 ('Wang et al. (2023): tapering in endurance athletes – systematic review and meta-analysis', 'taper', 'PLoS One 18(5):e0282838',
  'https://doi.org/10.1371/journal.pone.0282838',
  '14 studies: time-trial performance improved (SMD −0.45), VO2max/economy unchanged. Effective: ≤ 21 days, volume −41–60 %, intensity and frequency kept; larger gains after an overload block.',
  array['The peak block before the taper is the overload','The taper does not add fitness, it reveals it']),
 ('Vachon et al. (2021): tapering in team sports – neuromuscular and metabolic fitness', 'taper', 'Eur J Sport Sci 21(3):300–311',
  'https://doi.org/10.1080/17461391.2020.1736183',
